class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); enableEdgeToEdge(); setContent { SolaceTheme { SolaceApp() } } }
}

private data class Destination(val label: String, val icon: androidx.compose.ui.graphics.vector.ImageVector)
private val destinations = listOf(Destination("Map", Icons.Outlined.Map), Destination("History", Icons.Outlined.History), Destination("Places", Icons.Outlined.Home), Destination("Devices", Icons.Outlined.Devices), Destination("Settings", Icons.Outlined.Settings))

@Composable private fun SolaceApp() {
    var selected by remember { mutableIntStateOf(0) }
    Scaffold(containerColor = MaterialTheme.colorScheme.background, bottomBar = { NavigationBar(containerColor = MaterialTheme.colorScheme.surface) { destinations.forEachIndexed { index, item -> NavigationBarItem(selected = selected == index, onClick = { selected = index }, icon = { Icon(item.icon, contentDescription = item.label) }, label = { Text(item.label) }) } } }) { padding ->
        when (selected) { 0 -> MapScreen(Modifier.padding(padding)); 1 -> HistoryScreen(Modifier.padding(padding)); 2 -> PlacesScreen(Modifier.padding(padding)); 3 -> AccountScreen(Modifier.padding(padding)); else -> SettingsScreen(Modifier.padding(padding)) }
    }
}

@Composable private fun MapScreen(modifier: Modifier = Modifier) {
    val context = LocalContext.current
    var tracking by remember { mutableStateOf(context.getSharedPreferences("tracking", Context.MODE_PRIVATE).getBoolean("active", false)) }
    var locationGranted by remember { mutableStateOf(ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED) }
    val requestLocation = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { grants -> locationGranted = grants[Manifest.permission.ACCESS_FINE_LOCATION] == true || grants[Manifest.permission.ACCESS_COARSE_LOCATION] == true }
    LazyColumn(modifier = modifier.fillMaxSize().padding(horizontal = 20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
        item { Spacer(Modifier.height(12.dp)); BrandHeader("Your space, together") }
        item { Box(Modifier.fillMaxWidth().height(332.dp).clip(RoundedCornerShape(28.dp)).background(Brush.linearGradient(listOf(Color(0xFF25213A), Color(0xFF151321))))) {
            MapTexture(); Column(Modifier.align(Alignment.Center).padding(30.dp), horizontalAlignment = Alignment.CenterHorizontally) { Text(if (tracking) "Recording securely on this phone" else if (locationGranted) "Location sharing is ready" else "Your location stays on your phone", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold, textAlign = TextAlign.Center); Spacer(Modifier.height(8.dp)); Text(if (tracking) "Locations are saved offline until you choose to share." else if (locationGranted) "Start private offline recording when you’re ready." else "Allow location to record trips offline and share only with your chosen person.", color = MaterialTheme.colorScheme.onSurfaceVariant, textAlign = TextAlign.Center); Spacer(Modifier.height(20.dp)); Button(onClick = { if (!locationGranted) requestLocation.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION)) else if (!tracking) { startTracking(context); tracking = true } else { stopTracking(context); tracking = false } }) { Text(if (!locationGranted) "Allow location" else if (tracking) "Stop recording" else "Start recording") } }
            Surface(Modifier.align(Alignment.BottomStart).padding(16.dp), shape = RoundedCornerShape(30.dp), color = Color(0xDD302C47)) { Text("•  Offline recording", Modifier.padding(horizontal = 13.dp, vertical = 8.dp), color = Color(0xFFF2B8D2)) }
        } }
        item { StatusCard() }; item { SectionTitle("Together, on your terms") }; item { PrivacyCard("No partner connected", "Invite one person when you’re both ready.", "Create invitation") }; item { Spacer(Modifier.height(8.dp)) }
    }
}

private fun startTracking(context: Context) { ContextCompat.startForegroundService(context, Intent(context, LocationTrackingService::class.java)); context.getSharedPreferences("tracking", Context.MODE_PRIVATE).edit().putBoolean("active", true).apply() }
private fun stopTracking(context: Context) { context.stopService(Intent(context, LocationTrackingService::class.java)); context.getSharedPreferences("tracking", Context.MODE_PRIVATE).edit().putBoolean("active", false).apply() }
@Composable private fun MapTexture() { Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.SpaceEvenly) { repeat(4) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { repeat(5) { Box(Modifier.size(3.dp).background(Color(0xFF746A99), CircleShape)) } } } } }
@Composable private fun HistoryScreen(modifier: Modifier) { val context = LocalContext.current; val now = System.currentTimeMillis(); val dayStart = now - (now % 86_400_000); val points by AppDatabase.get(context).locationDao().observeBetween(dayStart, dayStart + 86_400_000).collectAsState(emptyList()); LazyColumn(modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) { item { Spacer(Modifier.height(12.dp)); BrandHeader("History") }; item { Text(DateFormat.getDateInstance(DateFormat.FULL).format(Date(now)), color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Card(shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)) { Column(Modifier.padding(20.dp)) { Text(if (points.isEmpty()) "No locations recorded today" else "${points.size} locations recorded today", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold); Spacer(Modifier.height(6.dp)); Text(if (points.isEmpty()) "Start recording on the Map tab. Your timeline remains on this device until sync is configured." else "GPS measurement times are preserved for every point.", color = MaterialTheme.colorScheme.onSurfaceVariant) } } }; items(points.size) { index -> val point = points[index]; Row(Modifier.fillMaxWidth().padding(vertical = 4.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text(DateFormat.getTimeInstance(DateFormat.SHORT).format(Date(point.recordedAt))); Text("±${point.accuracy.toInt()} m", color = MaterialTheme.colorScheme.onSurfaceVariant) } } } }
@Composable private fun PlacesScreen(modifier: Modifier) { val context = LocalContext.current; val dao = AppDatabase.get(context).locationDao(); val places by dao.observePlaces().collectAsState(emptyList()); val scope = rememberCoroutineScope(); var adding by remember { mutableStateOf(false) }; var name by remember { mutableStateOf("") }; var latitude by remember { mutableStateOf("") }; var longitude by remember { mutableStateOf("") }; if (adding) AlertDialog(onDismissRequest = { adding = false }, title = { Text("Add a place") }, text = { Column(verticalArrangement = Arrangement.spacedBy(8.dp)) { OutlinedTextField(name, { name = it }, label = { Text("Name") }); OutlinedTextField(latitude, { latitude = it }, label = { Text("Latitude") }); OutlinedTextField(longitude, { longitude = it }, label = { Text("Longitude") }) } }, confirmButton = { TextButton(onClick = { val lat = latitude.toDoubleOrNull(); val lon = longitude.toDoubleOrNull(); if (name.isNotBlank() && lat != null && lon != null && lat in -90.0..90.0 && lon in -180.0..180.0) { scope.launch { dao.savePlace(SavedPlaceEntity(UUID.randomUUID().toString(), name.trim(), lat, lon, 150f, System.currentTimeMillis())) }; adding = false; name = ""; latitude = ""; longitude = "" } }) { Text("Save") } }, dismissButton = { TextButton(onClick = { adding = false }) { Text("Cancel") } }); LazyColumn(modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { Spacer(Modifier.height(12.dp)); BrandHeader("Places") }; item { Text("Private places are stored locally on this device.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Button(onClick = { adding = true }) { Text("Add a place") } }; if (places.isEmpty()) item { PrivacyCard("No saved places", "Add Home, Work, or a custom location. Geofence alerts will be enabled in the next step.", "") }; items(places.size) { index -> val place = places[index]; Card(shape = RoundedCornerShape(18.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)) { Row(Modifier.fillMaxWidth().padding(18.dp), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text(place.name, fontWeight = FontWeight.SemiBold); Text("${place.radiusMeters.toInt()} m radius", color = MaterialTheme.colorScheme.onSurfaceVariant, style = MaterialTheme.typography.bodySmall) }; TextButton(onClick = { scope.launch { dao.deletePlace(place.id) } }) { Text("Delete") } } } } } }
@Composable private fun AccountScreen(modifier: Modifier) { val context = LocalContext.current; val auth = remember { SupabaseAuthRepository(context) }; val scope = rememberCoroutineScope(); var email by remember { mutableStateOf("") }; var password by remember { mutableStateOf("") }; var registering by remember { mutableStateOf(false) }; var message by remember { mutableStateOf<String?>(null) }; val session = auth.savedSession(); LazyColumn(modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { Spacer(Modifier.height(12.dp)); BrandHeader("Account & partner") }; if (!auth.isConfigured) item { PrivacyCard("Supabase isn’t configured", "Copy local.properties.example to local.properties and add your project URL and publishable key. The service-role key is never used in the app.", "") } else if (session != null) item { Card(shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer)) { Column(Modifier.padding(20.dp)) { Text("Signed in", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold); Text(session.email, color = MaterialTheme.colorScheme.onSurfaceVariant); Spacer(Modifier.height(12.dp)); Text("Pairing becomes available after the server migration is applied.", color = MaterialTheme.colorScheme.onSurfaceVariant) } } } else item { OutlinedTextField(email, { email = it }, label = { Text("Email") }, modifier = Modifier.fillMaxWidth()); OutlinedTextField(password, { password = it }, label = { Text("Password (at least 6 characters)") }, modifier = Modifier.fillMaxWidth()); Button(onClick = { if (email.isNotBlank() && password.length >= 6) scope.launch { message = "Contacting Supabase…"; val result = if (registering) auth.signUp(email.trim(), password) else auth.signIn(email.trim(), password); message = result.fold({ if (it.accessToken.isBlank()) "Check your email to confirm your account, then sign in." else "Signed in successfully." }, { it.message ?: "Authentication failed" }) } }, modifier = Modifier.fillMaxWidth()) { Text(if (registering) "Create account" else "Sign in") }; TextButton(onClick = { registering = !registering }) { Text(if (registering) "Already have an account? Sign in" else "Need an account? Create one") }; message?.let { Text(it, color = MaterialTheme.colorScheme.onSurfaceVariant) } } } }
@Composable private fun StatusCard() = Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer), shape = RoundedCornerShape(20.dp)) { Row(Modifier.fillMaxWidth().padding(18.dp), verticalAlignment = Alignment.CenterVertically) { Box(Modifier.size(11.dp).background(Color(0xFFF2B8D2), CircleShape)); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text("Private by default", fontWeight = FontWeight.SemiBold); Text("Sharing is off until you explicitly turn it on.", style = MaterialTheme.typography.bodySmall) }; Text("Learn", color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold) } }
@Composable private fun EmptyScreen(modifier: Modifier, title: String, heading: String, detail: String, action: String) { Column(modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.Center, horizontalAlignment = Alignment.CenterHorizontally) { Text(title.uppercase(), color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold); Spacer(Modifier.height(18.dp)); Text(heading, style = MaterialTheme.typography.headlineMedium, textAlign = TextAlign.Center, fontWeight = FontWeight.SemiBold); Spacer(Modifier.height(12.dp)); Text(detail, color = MaterialTheme.colorScheme.onSurfaceVariant, textAlign = TextAlign.Center); Spacer(Modifier.height(28.dp)); Button(onClick = {}) { Text(action) } } }
@Composable private fun SettingsScreen(modifier: Modifier = Modifier) { val context = LocalContext.current; var tracking by remember { mutableStateOf(context.getSharedPreferences("tracking", Context.MODE_PRIVATE).getBoolean("active", false)) }; LazyColumn(modifier.fillMaxSize().padding(20.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) { item { Spacer(Modifier.height(12.dp)); BrandHeader("Settings") }; item { Text("Control what you share, and when.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; item { Card(shape = RoundedCornerShape(20.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer)) { Row(Modifier.fillMaxWidth().padding(18.dp), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("Offline recording", fontWeight = FontWeight.SemiBold); Text(if (tracking) "Active — visible in the persistent notification" else "Stopped", style = MaterialTheme.typography.bodySmall) }; Button(onClick = { if (tracking) stopTracking(context) else startTracking(context); tracking = !tracking }) { Text(if (tracking) "Stop" else "Start") } } } }; item { Spacer(Modifier.height(8.dp)); SettingsGroup("Sharing", listOf("Location sharing" to "Paused", "Partner" to "Not connected")) }; item { SettingsGroup("Privacy", listOf("Data retention" to "Keep until deleted", "Nearby sync" to "Off")) }; item { SettingsGroup("Storage & maps", listOf("Offline maps" to "None downloaded", "Local history" to "On this device")) }; item { TextButton(onClick = {}, modifier = Modifier.fillMaxWidth()) { Text("Sign out") }; Spacer(Modifier.height(16.dp)) } } }
@Composable private fun SettingsGroup(title: String, rows: List<Pair<String, String>>) { Text(title, modifier = Modifier.padding(top = 12.dp), color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.SemiBold); Card(shape = RoundedCornerShape(20.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)) { Column { rows.forEachIndexed { i, row -> Row(Modifier.fillMaxWidth().padding(18.dp), horizontalArrangement = Arrangement.SpaceBetween) { Text(row.first); Text(row.second, color = MaterialTheme.colorScheme.onSurfaceVariant) }; if (i < rows.lastIndex) Box(Modifier.fillMaxWidth().height(1.dp).background(MaterialTheme.colorScheme.outlineVariant)) } } } }
@Composable private fun BrandHeader(subtitle: String) { Text("SOLACE", color = MaterialTheme.colorScheme.primary, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.ExtraBold); Spacer(Modifier.height(5.dp)); Text(subtitle, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.SemiBold) }
@Composable private fun SectionTitle(text: String) = Text(text, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold)
@Composable private fun PrivacyCard(title: String, text: String, action: String) = Card(shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)) { Column(Modifier.padding(20.dp)) { Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold); Spacer(Modifier.height(6.dp)); Text(text, color = MaterialTheme.colorScheme.onSurfaceVariant); Spacer(Modifier.height(14.dp)); Text(action, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold) } }
